print("Demo 1:")
def predict_output(components, rows=2, cols=3):
    sorted_comps = []
    for color_comp_list in components.values():
        sorted_comps.extend(sorted(color_comp_list, key=lambda x: -x['size']))

    flat_colors = []
    for comp in sorted_comps:
        flat_colors.extend([comp['color']] * comp['size'])

    result_flat = flat_colors[:rows*cols] + [0] * (rows*cols - len(flat_colors))
    return [result_flat[i:i+cols] for i in range(0, rows*cols, cols)]

